'use strict';
const videos=window.SEASLUGS.videos;
const regions=window.SEASLUGS.regions;
const grid=document.querySelector('#grid');
const search=document.querySelector('#search');
const dialog=document.querySelector('#player');
let selected='all';let opener=null;
const normalize=s=>s.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim();
document.querySelector('#total').textContent=`(${videos.length})`;
for(const b of document.querySelectorAll('[data-region]')){const n=b.dataset.region==='all'?videos.length:videos.filter(v=>v.region===b.dataset.region).length;const count=document.createElement('small');count.textContent=n;b.append(count);b.addEventListener('click',()=>{selected=b.dataset.region;render()})}
function play(v,button){opener=button;document.querySelector('#playerTitle').textContent=v.title;document.querySelector('#playerRegion').textContent=regions[v.region];document.querySelector('#youtubeLink').href=`https://www.youtube.com/watch?v=${v.id}`;const frame=document.createElement('iframe');frame.src=`https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.id)}?autoplay=1&rel=0`;frame.title=v.title;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';document.querySelector('#frame').replaceChildren(frame);dialog.showModal();document.body.style.overflow='hidden'}
function render(){const q=normalize(search.value);const found=videos.filter(v=>(selected==='all'||v.region===selected)&&normalize(v.title+' '+regions[v.region]).includes(q));for(const b of document.querySelectorAll('[data-region]')){const active=b.dataset.region===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}grid.replaceChildren();const frag=document.createDocumentFragment();found.forEach((v,index)=>{const article=document.createElement('article');article.className='card';const button=document.createElement('button');button.type='button';button.className='video-button';button.setAttribute('aria-label',`צפייה: ${v.title} — ${regions[v.region]}`);const wrap=document.createElement('span');wrap.className='image-wrap';const img=document.createElement('img');img.src=v.thumbnail;img.alt='';img.width=640;img.height=360;img.loading=index<6?'eager':'lazy';img.decoding='async';const icon=document.createElement('span');icon.className='play';icon.textContent='▶';icon.setAttribute('aria-hidden','true');wrap.append(img,icon);const info=document.createElement('span');info.className='card-info';const title=document.createElement('h3');title.textContent=v.title;if(/[\u0590-\u05ff]/.test(v.title))title.className='hebrew';const meta=document.createElement('span');meta.className='card-meta';const region=document.createElement('span');region.textContent=regions[v.region];const label=document.createElement('span');label.textContent='לצפייה';meta.append(region,label);info.append(title,meta);button.append(wrap,info);button.addEventListener('click',()=>play(v,button));article.append(button);frag.append(article)});grid.append(frag);document.querySelector('#resultCount').textContent=`${found.length} סרטונים`;document.querySelector('#empty').hidden=found.length>0}
search.addEventListener('input',render);document.querySelector('#reset').addEventListener('click',()=>{search.value='';selected='all';render();search.focus()});document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.querySelector('#frame').replaceChildren();document.body.style.overflow='';opener?.focus()});render();
